var a=[{title:`Tehnica ramatului`,text:`Pornește dintr-o poziție stabilă și trage spre coastele inferioare sau spre șold, în funcție de exercițiu. Lasă omoplații să se miște natural când brațele se extind și trag înapoi și nu arunca trunchiul ca să creezi inerție. Nu trebuie să îți forțezi coatele într-un singur unghi, iar amplitudinea se termină acolo unde o mai poți controla.`},{title:`Variante în funcție de echipament`,text:`Un ramat cu o singură ganteră lucrează fiecare parte separat și îți poți sprijini o mână pe o bancă sigură. Ramatul la cablu din șezut îți permite să reglezi sarcina în pași mici. Ramatul cu bandă elastică cere un punct de ancorare sigur, iar rezistența se schimbă pe parcursul repetării. Ramatul inversat cu greutatea corpului devine mai ușor pe măsură ce corpul e mai vertical și mai greu pe măsură ce se apropie de orizontală.`},{title:`Ce schimbă dificultatea`,text:`Unghiul trunchiului, sprijinul, lățimea mânerului, traseul coatelor, sarcina și amplitudinea schimbă cât de greu este un ramat. Un ramat cu pieptul sprijinit elimină nevoia de a menține o aplecare din șold, ceea ce ajută când vrei să-ți antrenezi spatele, nu rezistența la poziția aplecată. Este și o alegere bună când menținerea îndelungată a aplecării nu ți se potrivește. Notează separat variantele diferite de ramat, deoarece cifrele lor nu sunt interschimbabile.`},{title:`Greșeli tipice`,text:`Evită ridicarea puternică a umerilor, smucirea cu zona lombară sau scurtarea amplitudinii doar ca să ridici mai mult. Când poziția ți se strică, ușurează sarcina și încetinește faza de coborâre. Ramatul acasă folosind o masă sau un prosop este sigur doar dacă ancorarea și structura pot susține în mod sigur greutatea corpului tău în mișcare.`},{title:`Planificarea săptămânii`,text:`Împerechează ramatul cu împingerile orizontale pe parcursul săptămânii. Alege variante de ramat potrivite cu echipamentul tău, cu locul în care poți ancora sigur o bandă elastică și cu greutățile pe care le ai.`}];var r=[{label:`Biblioteca de exerciții ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: tehnica antrenamentului cu greutăți (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`NSCA: bazele siguranței și ale antrenamentului de forță`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var t={sections:a,sources:r};export{t as default,a as sections,r as sources};